import hashlib,json,os,pathlib
roots=[pathlib.Path(p) for p in ("/usr/local/cuda-13.0","/usr/local/lib/python3.12/dist-packages/nvidia","/usr/local/lib/python3.12/dist-packages/torch/lib")]
files=[]
for root in roots:
 for p in root.rglob("libcupti*"):
  if p.is_file():files.append({"path":str(p),"resolved":str(p.resolve()),"bytes":p.stat().st_size,"sha256":hashlib.sha256(p.read_bytes()).hexdigest()})
print(json.dumps({"LD_LIBRARY_PATH":os.environ.get("LD_LIBRARY_PATH"),"files":files},indent=2))
